def etkin_saat(gonullu, haftalik, hafta, devamsizlik):
    return gonullu * haftalik * hafta * (1 - devamsizlik)

def seans_kapasitesi(etkin, saha_payi, seans_suresi):
    return int((etkin * saha_payi) // seans_suresi)

etkin = etkin_saat(9, 3, 12, 0.15)
kapasite = seans_kapasitesi(etkin, 0.70, 1.5)
hedef = 90 * 2
ayni = etkin * 150

print("etkin saat :", round(etkin, 1))
print("kapasite   :", kapasite)
print("hedef      :", hedef)
print("acik       :", hedef - kapasite)
print("ayni deger :", round(ayni, 1))

def puan_farki(taban, sonra):
    return round(sonra - taban, 2)

def goreli_degisim(taban, sonra):
    return round((sonra - taban) / taban * 100, 2)

def hedefe_ulasma(ulasilan, hedef):
    return round(ulasilan / hedef * 100, 2)

def birim_maliyet(toplam, kisi):
    return round(toplam / kisi, 2)

taban, sonra = 22.0, 58.0
ulasilan, hedef = 51, 64
toplam = 4200 + 14400

print("puan farki   :", puan_farki(taban, sonra))
print("goreli %     :", goreli_degisim(taban, sonra))
print("hedefe ulasma:", hedefe_ulasma(ulasilan, hedef))
print("birim maliyet:", birim_maliyet(toplam, ulasilan))
